package ru.hryushki.accounts;

import android.content.Context;
import android.app.Activity;
import android.content.Intent;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
import org.json.*;
import java.math.BigDecimal;
import java.io.*;

@RunWith(AndroidJUnit4.class)
public class AccountingTest {
 static JSONObject op(long id,String type,String wh,String item,String qty,String amount)throws Exception{JSONObject o=new JSONObject();o.put("id",id);o.put("date","02.11.2026");o.put("type",type);o.put("warehouse",wh);o.put("item",item);o.put("qty",new BigDecimal(qty));o.put("amount",new BigDecimal(amount));return o;}
 static void append(JSONObject db,JSONObject o)throws Exception{Engine.rows(db,"operations").put(o);}
 static void eq(String n,BigDecimal actual){assertEquals(0,new BigDecimal(n).compareTo(actual));}
 @Test public void partnerCycleAndMaterials()throws Exception{JSONObject d=Engine.empty();append(d,op(1,"Покупка материалов",Engine.HOME,"Флис","1.5","600"));append(d,op(2,"Производство",Engine.HOME,"Лежанка","3","0"));append(d,op(3,"Передача партнёру",Engine.PARTNER,"Лежанка","2","0"));JSONObject sale=op(4,"Продажа",Engine.PARTNER,"Лежанка","1","550");sale.put("fee",20);sale.put("paid",50);sale.put("_cost",200);append(d,sale);append(d,op(5,"Выплата партнёра",Engine.PARTNER,"","0","480"));JSONObject direct=op(6,"Продажа",Engine.HOME,"Лежанка","1","500");direct.put("_cost",200);append(d,direct);Engine.Totals t=Engine.calculate(d,null,null);eq("1050",t.revenue);eq("20",t.expense);eq("400",t.cogs);eq("630",t.result());eq("0",t.debt);eq("430",t.cash);eq("1",t.stock.get(Engine.key(Engine.PARTNER,"Лежанка")));eq("1.5",t.stock.get(Engine.key(Engine.MATERIALS,"Флис")));}
 @Test public void editingAuditAndUnknownFieldsRoundTrip()throws Exception{JSONObject d=Engine.empty();d.put("custom",new JSONObject("{\"nested\":42}"));append(d,op(1,"Производство",Engine.HOME,"Арка","2","0"));JSONObject sale=op(2,"Продажа",Engine.HOME,"Арка","1","570");sale.put("customSale","keep");sale.put("paid",570);append(d,sale);JSONObject edit=Engine.copy(sale);edit.put("amount",600);edit.put("paid",600);JSONObject next=Engine.operationChange(d,edit,2);assertEquals("keep",Engine.rows(next,"operations").getJSONObject(1).getString("customSale"));assertEquals(42,next.getJSONObject("custom").getInt("nested"));assertEquals(570,Engine.rows(next,"_audit").getJSONObject(0).getJSONObject("before").getInt("amount"));assertEquals(2,Engine.rows(next,"operations").length());eq("600",Engine.calculate(next,null,null).revenue);assertEquals(1,Engine.calculate(next,null,null).unknown);JSONObject restored=DatabaseStore.parse(DatabaseStore.bytes(next));assertEquals(next.toString(),restored.toString());}
 @Test public void rejectOversellAndOverpayment()throws Exception{JSONObject d=Engine.empty();append(d,op(1,"Производство",Engine.HOME,"Арка","1","0"));try{JSONObject oversale=op(0,"Продажа",Engine.HOME,"Арка","2","100");oversale.put("paid",100);Engine.operationChange(d,oversale,0);fail("oversell accepted");}catch(IllegalArgumentException expected){}try{Engine.operationChange(d,op(0,"Выплата партнёра",Engine.PARTNER,"","0","100"),0);fail("overpayment accepted");}catch(IllegalArgumentException expected){}assertEquals(1,Engine.rows(d,"operations").length());}
 @Test public void voidAndPeriod()throws Exception{JSONObject d=Engine.empty();JSONObject start=op(1,"Корректировка склада",Engine.HOME,"Тоннель","3","0");start.put("date","Без даты");append(d,start);JSONObject sale=op(2,"Продажа",Engine.HOME,"Тоннель","1","550");append(d,sale);JSONObject next=Engine.voidOperation(d,2,"Возврат записи");Engine.Totals t=Engine.calculate(next,Engine.date("01.11.2026"),Engine.date("30.11.2026"));eq("0",t.revenue);eq("3",t.stock.get(Engine.key(Engine.HOME,"Тоннель")));assertEquals(1,Engine.rows(next,"_audit").length());assertFalse(Engine.active(Engine.rows(next,"operations").getJSONObject(1)));}
 @Test public void fractionalMaterialsAndDecimalMoney()throws Exception{JSONObject d=Engine.empty();append(d,op(1,"Покупка материалов",Engine.HOME,"Флис","0.3","0.10"));append(d,op(2,"Расход материалов",Engine.HOME,"Флис","0.1","0"));append(d,op(3,"Поступление",Engine.HOME,"","0","0.20"));Engine.Totals t=Engine.calculate(d,null,null);eq("0.2",t.stock.get(Engine.key(Engine.MATERIALS,"Флис")));eq("0.1",t.cash);}
 @Test public void skuVariantsAndHistoricalCosts()throws Exception{JSONObject d=Engine.empty();JSONObject a=new JSONObject("{\"name\":\"Лежанка зелёная\",\"sku\":\"LZ-001\",\"HomePrice\":680,\"PartnerPrice\":650,\"Cost\":300}");d=Engine.catalogChange(d,false,null,a);JSONObject b=Engine.copy(a);b.put("name","Лежанка принт");b.put("sku","LZ-002");b.put("HomePrice",800);d=Engine.catalogChange(d,false,null,b);JSONObject duplicate=Engine.copy(b);duplicate.put("name","Дубликат");duplicate.put("sku","lz-001");try{Engine.catalogChange(d,false,null,duplicate);fail("duplicate sku accepted");}catch(IllegalArgumentException expected){}append(d,op(1,"Производство",Engine.HOME,"Лежанка зелёная","1","0"));JSONObject sale=op(2,"Продажа",Engine.HOME,"Лежанка зелёная","1","680");sale.put("_cost",300);append(d,sale);a.put("Cost",450);JSONObject next=Engine.catalogChange(d,false,"Лежанка зелёная",a);eq("300",Engine.calculate(next,null,null).cogs);assertEquals(2,Engine.rows(next,"products").length());}
 @Test public void datesAndInvalidNumbers(){assertEquals(Engine.date("02.11.2026"),Engine.date("2026-11-02"));try{Engine.date("31.02.2026");fail();}catch(IllegalArgumentException expected){}try{Engine.decimal("NaN");fail();}catch(IllegalArgumentException expected){}}
 @Test public void atomicSaveRestoreAndRestart()throws Exception{Context ctx=InstrumentationRegistry.getInstrumentation().getTargetContext();DatabaseStore s=new DatabaseStore(ctx);JSONObject d=Engine.empty();d.put("persistMarker","saved");append(d,op(1,"Производство",Engine.HOME,"Тест","3","0"));s.save(d);DatabaseStore reopened=new DatabaseStore(ctx);assertEquals("saved",reopened.data.getString("persistMarker"));assertEquals(1,Engine.rows(reopened.data,"operations").length());File f=reopened.backup();JSONObject next=Engine.copy(reopened.data);next.put("persistMarker","changed");reopened.save(next);reopened.restore(f);assertEquals("saved",reopened.data.getString("persistMarker"));}
 @Test public void uiPagesAndEditors()throws Exception{android.app.Instrumentation i=InstrumentationRegistry.getInstrumentation();Intent launch=new Intent(i.getTargetContext(),MainActivity.class);launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity activity=i.startActivitySync(launch);i.runOnMainSync(()->{MainActivity a=(MainActivity)activity;for(String p:new String[]{"Обзор","Операции","Склад изделий","Товары и цены","Материалы","База и копии"})a.navigate(p);try{a.editOperation(null,"Продажа");a.editCatalog(false,null);a.editCatalog(true,null);}catch(Exception e){throw new RuntimeException(e);}a.editing=false;a.navigate("Обзор");assertEquals("",a.lastError);});i.waitForIdleSync();i.runOnMainSync(activity::finish);}
}
